386		submitMsg(t, state, "m100", "chain-a", "chain-b", 1, 100)
387		rep := advanceCLI(t, state, 1_700_000_000_000)
388		delivered := resultFor(t, rep, "m100")
389		if want := "delivered; proof verified by trusted header at height 100"; delivered.Status != "success" || delivered.Reason != want {
390			t.Fatalf("covered message must deliver via trusted height 100: %+v", delivered)
391		}
392		submitMsg(t, state, "m101", "chain-a", "chain-b", 2, 101)
393		rep = advanceCLI(t, state, 1_700_000_100_000)
394		waiting := resultFor(t, rep, "m101")
395		if waiting.Status != "waiting" || waiting.Reason != "waiting for trusted header covering height 101 (current 100)" {
396			t.Fatalf("untrusted header must not widen trusted coverage: %+v", waiting)
397		}
398	}
