1	package relayproof
2	
3	import (
4		"bytes"
5		"encoding/base64"
6		"errors"
7		"os"
8		"path/filepath"
9		"strings"
10		"testing"
11	)
12	
13	// Message payloads are arbitrary byte strings compared byte for byte in the
14	// same-id content check. The Go submit interface never requires a payload to
15	// be valid UTF-8: it may be empty, plain text, hold NUL bytes or stray
16	// 0xFF/0xFE bytes, or mix text with them. Such a payload must survive the
17	// submit echo, single and full queries, an identical resubmit, reopen and log
18	// compaction exactly — JSON string encoding would otherwise silently rewrite
19	// the invalid bytes to U+FFFD, so a byte-identical resubmit of an
20	// unterminated message would wrongly conflict after a reopen.
21	
22	const replacementCharPayload = "�"
23	
24	// payloadEnvelope builds a non-terminal envelope carrying payload; each call
25	// site supplies a distinct nonce so processing one message can never replay
26	// another.
27	func payloadEnvelope(id string, nonce uint64, payload string) Envelope {
28		return Envelope{
29			Message: Message{
30				ID:      id,
31				From:    "chain-a",
32				To:      "chain-b",
33				Nonce:   nonce,
34				Payload: payload,
35				ProofAt: 90,
36			},
37		}
38	}
39	
40	// Every payload shape must come back byte-identical from the submit echo, a
41	// single Query and the full Queries listing.
42	func TestPayloadArbitraryBytesPreservedInInstance(t *testing.T) {
43		q, _ := openTempQueue(t)
44		defer q.Close()
45	
46		names := []string{"empty", "plain", "nul", "ff", "fe", "fffe", "mixed", "replacement"}
47		payloads := map[string]string{
48			"empty":       "",
49			"plain":       "hello",
50			"nul":         "a\x00b\x00",
51			"ff":          string([]byte{0xFF}),
52			"fe":          string([]byte{0xFE}),
53			"fffe":        string([]byte{0xFF, 0xFE}),
54			"mixed":       "pre\x00mid" + string([]byte{0xFF, 0xFE}) + "post",
55			"replacement": replacementCharPayload,
56		}
57		for i, name := range names {
58			if _, err := q.Submit(payloadEnvelope(name, uint64(i+1), payloads[name])); err != nil {
59				t.Fatalf("submit %s: %v", name, err)
60			}
61		}
62	
63		for i, name := range names {
64			want := payloads[name]
65			qy, ok := q.Query(name)
66			if !ok {
67				t.Fatalf("missing %s", name)
68			}
69			if !bytes.Equal([]byte(qy.Payload), []byte(want)) {
70				t.Fatalf("Query payload for %s changed:\nwant % x\ngot  % x", name, want, qy.Payload)
71			}
72			// An identical resubmit of an unterminated message returns the existing
73			// record byte-for-byte and adds nothing.
74			echo, err := q.Submit(payloadEnvelope(name, uint64(i+1), want))
75			if err != nil {
76				t.Fatalf("identical resubmit %s: %v", name, err)
77			}
78			if echo.Msg.Message.Payload != want {
79				t.Fatalf("resubmit echo payload for %s changed", name)
80			}
81		}
82		all := q.Queries()
83		if len(all) != len(names) {
84			t.Fatalf("identical resubmits must not add records: got %d rows", len(all))
85		}
86		for i, qy := range all {
87			if qy.ID != names[i] || qy.Payload != payloads[names[i]] {
88				t.Fatalf("Queries[%d] = (%s, % x), want (%s, % x)",
89					i, qy.ID, qy.Payload, names[i], payloads[names[i]])
90			}
91		}
92	}
93	
94	// 0xFF, 0xFE and the legal character U+FFFD are three different payloads: an
95	// identical-byte resubmit is the existing record, while changing any single
96	// byte — or submitting the visually similar replacement character — is a
97	// content conflict that leaves the original record untouched. The same holds
98	// after close/reopen and after a forced compaction (with a terminal record in
99	// the snapshot) plus reopen.
100	func TestPayloadInvalidBytesDistinctAcrossPersistenceBoundaries(t *testing.T) {
101		payFF := string([]byte{0xFF})
102		payFE := string([]byte{0xFE})
103		payMixed := "pre" + string([]byte{0xFF}) + "post"
104	
105		originals := map[string]string{
106			"ff":    payFF,
107			"fe":    payFE,
108			"mixed": payMixed,
109			"ufffd": replacementCharPayload,
110		}
111		nonces := map[string]uint64{"ff": 1, "fe": 2, "mixed": 3, "ufffd": 4}
112	
113		check := func(t *testing.T, q *Queue) {
114			t.Helper()
115			before := len(q.Queries())
116			for id, want := range originals {
117				echo, err := q.Submit(payloadEnvelope(id, nonces[id], want))
118				if err != nil {
119					t.Fatalf("identical resubmit %s: %v", id, err)
120				}
121				if echo.Msg.Message.Payload != want {
122					t.Fatalf("resubmit %s changed payload: % x", id, echo.Msg.Message.Payload)
123				}
124			}
125			if len(q.Queries()) != before {
126				t.Fatalf("identical resubmits must not add records: %d -> %d", before, len(q.Queries()))
127			}
128	
129			// One-byte changes and the look-alike legal character all conflict, no
130			// matter which live status (pending or waiting) the record is in.
131			for _, c := range []struct {
132				id  string
133				bad string
134			}{
135				{"ff", payFE},
136				{"ff", replacementCharPayload},
137				{"fe", payFF},
138				{"fe", replacementCharPayload},
139				{"mixed", replacementCharPayload},
140				{"ufffd", payFF},
141				{"ufffd", payFE},
142			} {
143				if _, err := q.Submit(payloadEnvelope(c.id, nonces[c.id], c.bad)); !errors.Is(err, ErrConflict) {
144					t.Fatalf("id %s resubmitted with payload % x must conflict: %v", c.id, c.bad, err)
145				}
146			}
147	
148			// Originals are untouched.
149			for id, p := range originals {
150				qy, ok := q.Query(id)
151				if !ok || qy.Payload != p {
152					t.Fatalf("original payload for %s changed after conflicts: ok=%v got % x want % x",
153						id, ok, qy.Payload, p)
154				}
155			}
156		}
157	
158		dir := t.TempDir()
159		q, err := Open(dir)
160		if err != nil {
161			t.Fatal(err)
162		}
163		for id, p := range originals {
164			if _, err := q.Submit(payloadEnvelope(id, nonces[id], p)); err != nil {
165				t.Fatalf("submit %s: %v", id, err)
166			}
167		}
168		t.Run("same instance", func(t *testing.T) { check(t, q) })
169		if err := q.Close(); err != nil {
170			t.Fatal(err)
171		}
172	
173		q = reopen(t, dir)
174		t.Run("after reopen", func(t *testing.T) { check(t, q) })
175	
176		// Drive the records to waiting and one to success so the forced snapshot
177		// carries post-processing state entries as well as submit entries.
178		q.RegisterSource("chain-a")
179		q.UpsertHeader(Header{Chain: "chain-a", Height: 1, Root: "r", Trusted: true})
180		term := Envelope{
181			Message: Message{
182				ID: "term", From: "chain-a", To: "chain-b", Nonce: 99,
183				Payload: "done" + string([]byte{0xFF}), ProofAt: 1,
184			},
185		}
186		if _, err := q.Submit(term); err != nil {
187			t.Fatal(err)
188		}
189		if _, err := q.Advance(1000); err != nil {
190			t.Fatal(err)
191		}
192		if st, _ := q.Query("term"); st.Status != StatusSuccess || st.Payload != term.Message.Payload {
193			t.Fatalf("term not delivered with payload intact: %+v", st)
194		}
195		if err := q.store.compact(q.snapshot()); err != nil {
196			t.Fatalf("compact: %v", err)
197		}
198		if err := q.Close(); err != nil {
199			t.Fatal(err)
200		}
201	
202		q = reopen(t, dir)
203		t.Run("after compaction and reopen", func(t *testing.T) { check(t, q) })
204		if st, ok := q.Query("term"); !ok || st.Payload != term.Message.Payload || st.Status != StatusSuccess {
205			t.Fatalf("terminal payload lost in compaction: ok=%v %+v", ok, st)
206		}
207		if err := q.Close(); err != nil {
208			t.Fatal(err)
209		}
210	
211		// The on-disk log stores invalid bytes base64-encoded and never the
212		// replacement character.
213		raw, err := os.ReadFile(filepath.Join(dir, logName))
214		if err != nil {
215			t.Fatal(err)
216		}
217		if !bytes.Contains(raw, []byte(`"payloadB64":"`)) {
218			t.Fatalf("invalid-UTF-8 payload not stored byte-exactly: %s", raw)
219		}
220		// "ufffd" legitimately serializes its U+FFFD payload as plain JSON, so
221		// assert only that the all-invalid-byte payloads left no replacement runs:
222		// the base64 encodings of 0xFF and 0xFE must be present.
223		if !bytes.Contains(raw, []byte(base64.StdEncoding.EncodeToString([]byte{0xFF}))) ||
224			!bytes.Contains(raw, []byte(base64.StdEncoding.EncodeToString([]byte{0xFE}))) {
225			t.Fatalf("log is missing the base64 payload bytes: %s", raw)
226		}
227	}
228	
229	// Valid-UTF-8 payloads — plain text, empty, NUL bytes, U+FFFD itself — keep
230	// the historical plain "payload" field, so existing state directories, the
231	// CLI text interface and the README examples stay byte-compatible on disk.
232	func TestPayloadValidUTF8KeepsHistoricalEncoding(t *testing.T) {
233		dir := t.TempDir()
234		q, err := Open(dir)
235		if err != nil {
236			t.Fatal(err)
237		}
238		cases := []struct {
239			id string
240			p  string
241		}{
242			{"plain", "hello"},
243			{"empty", ""},
244			{"nul", "a\x00b"},
245			{"ufffd", replacementCharPayload},
246		}
247		for i, c := range cases {
248			if _, err := q.Submit(payloadEnvelope(c.id, uint64(i+1), c.p)); err != nil {
249				t.Fatalf("submit %q: %v", c.p, err)
250			}
251		}
252		if err := q.Close(); err != nil {
253			t.Fatal(err)
254		}
255	
256		raw, err := os.ReadFile(filepath.Join(dir, logName))
257		if err != nil {
258			t.Fatal(err)
259		}
260		if bytes.Contains(raw, []byte("payloadB64")) {
261			t.Fatalf("valid-UTF-8 payloads must keep the plain payload field: %s", raw)
262		}
263		if !bytes.Contains(raw, []byte(`"payload":"hello"`)) {
264			t.Fatalf("plain payload missing from log: %s", raw)
265		}
266	
267		q = reopen(t, dir)
268		defer q.Close()
269		echo, err := q.Submit(payloadEnvelope("plain", 1, "hello"))
270		if err != nil || echo.Msg.Message.Payload != "hello" {
271			t.Fatalf("plain payload resubmit after reopen: rec=%+v err=%v", echo, err)
272		}
273		if _, err := q.Submit(payloadEnvelope("plain", 1, string([]byte{0xFF}))); !errors.Is(err, ErrConflict) {
274			t.Fatalf("invalid byte 0xFF must differ from every text payload: %v", err)
275		}
276	}
277	
278	// An unterminated waiting message whose identical resubmit happens after a
279	// reopen must return the existing waiting record — schedule unchanged —
280	// rather than a content conflict, because the saved payload bytes equal the
281	// submitted bytes. Changing one byte conflicts and leaves the schedule alone.
282	func TestPayloadInvalidBytesWaitingResubmitAfterReopenKeepsSchedule(t *testing.T) {
283		pay := "w" + string([]byte{0x00, 0xFF, 0xFE})
284		env := payloadEnvelope("w", 7, pay)
285		env.Message.ProofAt = 100 // no trusted header covers it -> waiting
286	
287		dir := t.TempDir()
288		q, err := Open(dir)
289		if err != nil {
290			t.Fatal(err)
291		}
292		q.RegisterSource("chain-a")
293		if _, err := q.Submit(env); err != nil {
294			t.Fatal(err)
295		}
296		if _, err := q.Advance(1000); err != nil {
297			t.Fatal(err)
298		}
299		st, _ := q.Query("w")
300		if st.Status != StatusWaiting || st.Attempts != 1 || st.NextRetry != 2000 {
301			t.Fatalf("unexpected pre-reopen state: %+v", st)
302		}
303		if err := q.Close(); err != nil {
304			t.Fatal(err)
305		}
306	
307		q = reopen(t, dir)
308		defer q.Close()
309		echo, err := q.Submit(env)
310		if err != nil {
311			t.Fatalf("byte-identical resubmit after reopen must return existing record: %v", err)
312		}
313		if echo.Msg.Message.Payload != pay || echo.Status != StatusWaiting ||
314			echo.Attempts != 1 || echo.NextRetry != 2000 {
315			t.Fatalf("resubmit must not reschedule or rewrite payload: %+v", echo)
316		}
317		if len(q.Queries()) != 1 {
318			t.Fatal("resubmit must not add a record")
319		}
320		bad := env
321		bad.Message.Payload = "w" + string([]byte{0x00, 0xFF, 0x00})
322		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
323			t.Fatalf("one-byte payload change must conflict: %v", err)
324		}
325		st2, _ := q.Query("w")
326		if st2.Payload != pay || st2.Attempts != 1 || st2.NextRetry != 2000 {
327			t.Fatalf("conflicting resubmit changed the record: %+v", st2)
328		}
329	}
330	
331	// invalidPayloadFrameSize returns the real framed size of a submit entry
332	// carrying tmpl's exact fields with an invalid-UTF-8 payload of n bytes; the
333	// seq-0 omit behavior matches the real queue's first submit.
334	func invalidPayloadFrameSize(t *testing.T, tmpl Envelope, n int) int64 {
335		t.Helper()
336		q, _ := openTempQueue(t)
337		defer q.Close()
338		if err := q.RegisterSource("chain-a"); err != nil {
339			t.Fatal(err)
340		}
341		if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
342			t.Fatal(err)
343		}
344		if _, err := q.Advance(1000); err != nil {
345			t.Fatal(err)
346		}
347		tmpl.Message.Payload = strings.Repeat("\xff", n)
348		before := q.store.size
349		if _, err := q.Submit(tmpl); err != nil {
350			t.Fatal(err)
351		}
352		return q.store.size - before
353	}
354	
355	// Automatic threshold compaction, triggered by an ordinary Submit, must carry
356	// invalid-UTF-8 payloads byte-exactly into the snapshot, including the
357	// oversized payload that supplies the bulk and the small submit that crosses
358	// the threshold; both read identically after reopen.
359	func TestPayloadInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
360		const margin int64 = 4096
361	
362		// Measure the real framed sizes in a gauge queue: size after
363		// source+header+one checkpoint (gaugeBase), the checkpoint frame, the
364		// crossing small submit frame, and the invalid-payload frame math at seq 0.
365		gq, _ := openTempQueue(t)
366		if err := gq.RegisterSource("chain-a"); err != nil {
367			t.Fatal(err)
368		}
369		if err := gq.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
370			t.Fatal(err)
371		}
372		gaugeBase := gq.store.size
373		if _, err := gq.Advance(1000); err != nil {
374			t.Fatal(err)
375		}
376		checkpoint := gq.store.size - gaugeBase
377		gq.Close()
378	
379		cross := payloadEnvelope("cross", 2, "x"+string([]byte{0xFF}))
380		filler := payloadEnvelope("filler", 1, "") // payload length is filled in below
381	
382		// Measure the crossing frame at seq 1 (a placeholder occupies seq 0, as the
383		// filler does in the real queue) in a setup identical to the real one.
384		gq2, _ := openTempQueue(t)
385		if err := gq2.RegisterSource("chain-a"); err != nil {
386			t.Fatal(err)
387		}
388		if err := gq2.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
389			t.Fatal(err)
390		}
391		if _, err := gq2.Advance(1000); err != nil {
392			t.Fatal(err)
393		}
394		if _, err := gq2.Submit(Envelope{Message: Message{
395			ID: "gauge-seq0", From: "chain-a", To: "chain-b", Nonce: 998,
396			Payload: "placeholder", ProofAt: 1,
397		}}); err != nil {
398			t.Fatal(err)
399		}
400		beforeCross := gq2.store.size
401		if _, err := gq2.Submit(cross); err != nil {
402			t.Fatal(err)
403		}
404		crossFrame := gq2.store.size - beforeCross
405		gq2.Close()
406	
407		// Invalid payloads serialize as base64: frame(n) = overhead + EncodedLen(n),
408		// measured for the seq-0 filler (whose seq is JSON-omitted).
409		const probeLen = 4096
410		probeFrame := invalidPayloadFrameSize(t, filler, probeLen)
411		overhead := probeFrame - int64(base64.StdEncoding.EncodedLen(probeLen))
412		targetFillerFrame := compactThreshold - margin - gaugeBase - checkpoint - crossFrame
413		if targetFillerFrame <= overhead {
414			t.Fatalf("setup arithmetic leaves no room for filler: target=%d overhead=%d", targetFillerFrame, overhead)
415		}
416		// Largest invalid byte count whose framed submit stays at the target size.
417		var fillerLen int
418		for lo, hi := 0, int(targetFillerFrame); ; {
419			mid := (lo + hi + 1) / 2
420			if overhead+int64(base64.StdEncoding.EncodedLen(mid)) <= targetFillerFrame {
421				lo = mid
422			} else {
423				hi = mid - 1
424			}
425			if lo == hi {
426				fillerLen = lo
427				break
428			}
429		}
430		filler.Message.Payload = strings.Repeat("\xff", fillerLen)
431	
432		dir := t.TempDir()
433		q, err := Open(dir)
434		if err != nil {
435			t.Fatal(err)
436		}
437		defer q.Close()
438		if err := q.RegisterSource("chain-a"); err != nil {
439			t.Fatal(err)
440		}
441		if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
442			t.Fatal(err)
443		}
444		if q.store.size != gaugeBase {
445			t.Fatalf("base mismatch: gauge %d real %d", gaugeBase, q.store.size)
446		}
447	
448		// Equal-time checkpoint padding (legal with no messages yet) so the small
449		// crossing submit is exactly what crosses 4 MiB; every checkpoint but one
450		// is dropped by the snapshot, which therefore lands margin below.
451		nCheckpoints := int(margin/checkpoint) + 2
452		for i := 0; i < nCheckpoints; i++ {
453			if _, err := q.Advance(1000); err != nil {
454				t.Fatal(err)
455			}
456		}
457		if q.store.size > compactThreshold {
458			t.Fatalf("padding crossed the threshold early: size=%d", q.store.size)
459		}
460		if _, err := q.Submit(filler); err != nil {
461			t.Fatalf("filler submit: %v", err)
462		}
463		if q.store.size > compactThreshold {
464			t.Fatalf("filler crossed the threshold before the crossing submit: size=%d", q.store.size)
465		}
466		if _, err := q.Submit(cross); err != nil {
467			t.Fatalf("crossing submit: %v", err)
468		}
469		if q.store.size > compactThreshold {
470			t.Fatalf("auto-compaction did not shrink the log below the threshold: size=%d", q.store.size)
471		}
472		if err := q.Close(); err != nil {
473			t.Fatal(err)
474		}
475	
476		q = reopen(t, dir)
477		defer q.Close()
478		got, ok := q.Query("filler")
479		if !ok {
480			t.Fatal("filler missing after auto compaction and reopen")
481		}
482		if got.Payload != filler.Message.Payload {
483			t.Fatalf("filler payload changed across auto compaction:\nwant len=%d\ngot  len=%d",
484				len(filler.Message.Payload), len(got.Payload))
485		}
486		if got, ok := q.Query("cross"); !ok || got.Payload != cross.Message.Payload {
487			t.Fatalf("crossing payload lost across auto compaction: ok=%v % x", ok, got.Payload)
488		}
489		// Byte-identical resubmits stay idempotent against the compacted records.
490		if _, err := q.Submit(filler); err != nil {
491			t.Fatalf("filler identical resubmit after compaction: %v", err)
492		}
493		if _, err := q.Submit(cross); err != nil {
494			t.Fatalf("cross identical resubmit after compaction: %v", err)
495		}
496		if len(q.Queries()) != 2 {
497			t.Fatalf("identical resubmits added records: %+v", q.Queries())
498		}
499	}
500	
501	// Existing state directories keep working: payloads an older build saved as
502	// plain JSON — ordinary text, empty and payloads already rewritten to U+FFFD —
503	// are read at face value. The lost bytes are never guessed: the replacement
504	// character stays that payload, and resubmitting the original invalid bytes
505	// conflicts with it.
506	func TestPayloadLegacyRecordsReadAtFaceValue(t *testing.T) {
507		dir := t.TempDir()
508		var raw []byte
509		raw = append(raw, logMagic...)
510		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
511		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
512			T: kindSubmit, Seq: 0, ID: "txt", From: "a", To: "b", Nonce: 1,
513			Payload: "legacy text", ProofAt: 10,
514		}))...)
515		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
516			T: kindSubmit, Seq: 1, ID: "empty", From: "a", To: "b", Nonce: 2, ProofAt: 10,
517		}))...)
518		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
519			T: kindSubmit, Seq: 2, ID: "lost", From: "a", To: "b", Nonce: 3,
520			Payload: replacementCharPayload, ProofAt: 10,
521		}))...)
522		writeRawLog(t, dir, raw)
523	
524		q := reopen(t, dir)
525		defer q.Close()
526		if got, ok := q.Query("txt"); !ok || got.Payload != "legacy text" {
527			t.Fatalf("legacy text payload: ok=%v %q", ok, got.Payload)
528		}
529		if got, ok := q.Query("empty"); !ok || got.Payload != "" {
530			t.Fatalf("legacy empty payload: ok=%v %q", ok, got.Payload)
531		}
532		if got, ok := q.Query("lost"); !ok || got.Payload != replacementCharPayload {
533			t.Fatalf("legacy replacement payload must be taken at face value: ok=%v %x", ok, got.Payload)
534		}
535		lost := Envelope{Message: Message{ID: "lost", From: "a", To: "b", Nonce: 3,
536			Payload: replacementCharPayload, ProofAt: 10}}
537		if _, err := q.Submit(lost); err != nil {
538			t.Fatalf("saved replacement character must resubmit as itself: %v", err)
539		}
540		lost.Message.Payload = string([]byte{0xFF})
541		if _, err := q.Submit(lost); !errors.Is(err, ErrConflict) {
542			t.Fatalf("original invalid bytes must not be guessed back: %v", err)
543		}
544	}
545	
546	// A checksum-valid record carrying both payload fields, or an undecodable
547	// payloadB64, is an inconsistent record no build writes: opening returns
548	// ErrCorrupt and leaves the file byte-for-byte untouched — the payload is
549	// never treated as empty or as replacement-filled text.
550	func TestPayloadB64InconsistentRecordsRejected(t *testing.T) {
551		for name, e := range map[string]*logEntry{
552			"both payload and payloadB64": {
553				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
554				Payload: "x", PayloadB64: "eA==", ProofAt: 10,
555			},
556			"undecodable payloadB64": {
557				T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1,
558				PayloadB64: "!!!not-base64!!!", ProofAt: 10,
559			},
560		} {
561			t.Run(name, func(t *testing.T) {
562				dir := t.TempDir()
563				var raw []byte
564				raw = append(raw, logMagic...)
565				raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
566				raw = append(raw, encodeFrame(mustMarshal(e))...)
567				writeRawLog(t, dir, raw)
568				assertCorruptAndUntouched(t, dir, raw)
569			})
570		}
571	}
