31	// original record keeps every field, its pending state and its submission
32	// position, nothing new is persisted, and an identical resubmit afterwards
33	// still returns the original.
34	func TestSubmitConflictForEverySingleContentField(t *testing.T) {
35		base := fullEnvelope("m")
36		cases := []struct {
37			name   string
38			mutate func(Envelope) Envelope
39		}{
40			{"source chain", func(e Envelope) Envelope { e.Message.From = "chain-other"; return e }},
41			{"destination chain", func(e Envelope) Envelope { e.Message.To = "chain-c"; return e }},
42			{"nonce", func(e Envelope) Envelope { e.Message.Nonce = 8; return e }},
