44			{"proof height", func(e Envelope) Envelope { e.Message.ProofAt = 91; return e }},
45			{"absolute expiry", func(e Envelope) Envelope { e.ExpiresAt = 9_000_000_000_001; return e }},
46			// Explicit zero values are real content too: turning the expiry off
47			// after a finite expiry was stored must conflict.
48			{"expiry to never", func(e Envelope) Envelope { e.ExpiresAt = 0; return e }},
49			{"payload to empty", func(e Envelope) Envelope { e.Message.Payload = ""; return e }},
50		}
51		for _, tc := range cases {
52			t.Run(tc.name, func(t *testing.T) {
53				q, _ := openTempQueue(t)
54				defer q.Close()
55	
56				first, err := q.Submit(base)
57				if err != nil {
58					t.Fatal(err)
59				}
60				changed := tc.mutate(base)
61				if _, err := q.Submit(changed); !errors.Is(err, ErrConflict) {
62					t.Fatalf("want ErrConflict, got %v", err)
63				}
64	
65				if len(q.records) != 1 || len(q.order) != 1 || q.order[0] != "m" || q.nextSeq != 1 {
66					t.Fatalf("rejected submit must persist nothing: records=%d order=%v nextSeq=%d",
67						len(q.records), q.order, q.nextSeq)
68				}
69				got := statusOf(t, q, "m")
70				if got.Msg != base {
71					t.Fatalf("original content overwritten:\nwant %+v\ngot  %+v", base, got.Msg)
72				}
73				if got.Status != StatusPending || got.Reason != "awaiting first processing" ||
74					got.Attempts != 0 || got.NextRetry != 0 {
75					t.Fatalf("pending state changed on conflict: %+v", got)
76				}
77	
78				// The rejected submit must not have consumed a seq: a later new
79				// message still takes seq 1, and an identical resubmit still works.
80				if again, err := q.Submit(base); err != nil || again.Seq != first.Seq {
81					t.Fatalf("identical resubmit after rejected submit must return original (seq %d): rec=%+v err=%v",
82						first.Seq, again, err)
83				}
84				later := fullEnvelope("n")
85				rec, err := q.Submit(later)
86				if err != nil {
87					t.Fatal(err)
88				}
89				if rec.Seq != 1 {
90					t.Fatalf("rejected submit must not consume a seq number: got %d", rec.Seq)
91				}
92			})
93		}
94	}
95	
96	// Content identity must not collapse to the replay triple: same id and same
97	// (from, to, nonce) but different payload, proof height or expiry is still a
98	// conflict, in both comparison directions.
99	func TestSubmitConflictNotJudgedByIdOrNonceOnly(t *testing.T) {
100		q, _ := openTempQueue(t)
101		defer q.Close()
102	
103		first := fullEnvelope("m")
104		if _, err := q.Submit(first); err != nil {
105			t.Fatal(err)
106		}
107		second := first
108		second.Message.Payload = "different"
109		second.Message.ProofAt = 91
110		second.ExpiresAt = 1
111		if _, err := q.Submit(second); !errors.Is(err, ErrConflict) {
112			t.Fatalf("same id/nonce triple but different content must conflict: %v", err)
113		}
114		// And the reverse ordering of the two contents must give the same verdict.
115		if _, err := q.Submit(first); err != nil {
116			t.Fatalf("original content must still resubmit idempotently after rejection: %v", err)
117		}
118	}
119	
120	// A successful idempotent resubmit on a pending record returns a value equal to
121	// the first submit echo and to what Query reports; Queries still lists the id
122	// exactly once with its original seq, including across a reopen.
123	func TestSubmitIdenticalPendingEchoMatchesQueryAndSurvivesReopen(t *testing.T) {
124		dir := t.TempDir()
125		q, err := Open(dir)
126		if err != nil {
127			t.Fatal(err)
128		}
129		want := fullEnvelope("m")
130		first, err := q.Submit(want)
131		if err != nil {
132			t.Fatal(err)
133		}
134		again, err := q.Submit(want)
135		if err != nil {
136			t.Fatalf("identical pending resubmit: %v", err)
137		}
138		if *again != *first {
139			t.Fatalf("resubmit echo differs from first submit:\nfirst=%+v\nagain=%+v", first, again)
140		}
141		qy, ok := q.Query("m")
142		if !ok {
143			t.Fatal("missing m")
144		}
145		if qy.ID != want.Message.ID || qy.From != want.Message.From || qy.To != want.Message.To ||
146			qy.Nonce != want.Message.Nonce || qy.Payload != want.Message.Payload ||
147			qy.ProofAt != want.Message.ProofAt || qy.ExpiresAt != want.ExpiresAt ||
148			qy.Status != StatusPending || qy.Attempts != 0 || qy.NextRetry != 0 {
149			t.Fatalf("query disagrees with resubmit echo: %+v echo=%+v", qy, again)
150		}
151		if all := q.Queries(); len(all) != 1 || all[0].ID != "m" {
152			t.Fatalf("listing must contain the id exactly once: %+v", all)
153		}
154		if err := q.Close(); err != nil {
155			t.Fatal(err)
156		}
157	
158		q2, err := Open(dir)
159		if err != nil {
160			t.Fatal(err)
161		}
162		defer q2.Close()
163		if _, err := q2.Submit(want); err != nil {
164			t.Fatalf("identical resubmit after reopen must still be idempotent: %v", err)
165		}
166		if all := q2.Queries(); len(all) != 1 || all[0].ID != "m" || all[0].Payload != want.Message.Payload {
167			t.Fatalf("duplicate persisted across reopen: %+v", all)
168		}
169	}
170	
171	// While waiting, an identical resubmit returns the CURRENT waiting record —
172	// status, reason, attempts and next retry time all populated — equal to the
173	// single Query view; it neither processes early nor reschedules. The message
174	// later delivers exactly on its original schedule.
175	func TestSubmitIdenticalWaitingReturnsCurrentRecord(t *testing.T) {
176		q, _ := openTempQueue(t)
177		defer q.Close()
178		q.RegisterSource("chain-a")
179		q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true})
180	
181		env := Envelope{
182			Message:   Message{ID: "w", From: "chain-a", To: "chain-b", Nonce: 8, Payload: "world", ProofAt: 110},
183			ExpiresAt: 9_000_000_000_000,
184		}
185		if _, err := q.Submit(env); err != nil {
186			t.Fatal(err)
187		}
188		rep, err := q.Advance(1_700_000_000_000)
189		if err != nil {
190			t.Fatal(err)
191		}
192		if len(rep.Results) != 1 || rep.Results[0].Status != StatusWaiting {
193			t.Fatalf("setup: want one waiting result, got %+v", rep.Results)
194		}
195	
196		echo, err := q.Submit(env)
197		if err != nil {
198			t.Fatalf("identical waiting resubmit: %v", err)
199		}
200		if echo.Status != StatusWaiting || echo.Attempts != 1 || echo.NextRetry != 1_700_000_001_000 ||
201			echo.Msg != env {
202			t.Fatalf("resubmit must return the current waiting record: %+v", echo)
203		}
204		qy, ok := q.Query("w")
205		if !ok {
206			t.Fatal("missing w")
207		}
208		if qy.Status != echo.Status || qy.Reason != echo.Reason || qy.Attempts != echo.Attempts ||
209			qy.NextRetry != echo.NextRetry || qy.ExpiresAt != echo.Msg.ExpiresAt {
210			t.Fatalf("query disagrees with waiting echo: query=%+v echo=%+v", qy, echo)
211		}
212		if wantReason := "waiting for trusted header covering height 110 (current 100)"; qy.Reason != wantReason {
213			t.Fatalf("waiting reason wrong: %q", qy.Reason)
214		}
215		if len(q.order) != 1 || len(q.records) != 1 {
216			t.Fatalf("waiting duplicate must not add a queue entry: order=%v records=%d", q.order, len(q.records))
217		}
218	
219		// Early advance (before retry) processes nothing and keeps the schedule.
220		rep, err = q.Advance(1_700_000_000_500)
221		if err != nil {
222			t.Fatal(err)
223		}
224		if len(rep.Results) != 0 {
225			t.Fatalf("nothing due mid-backoff, got %+v", rep.Results)
226		}
227		echo2, err := q.Submit(env)
228		if err != nil {
229			t.Fatal(err)
230		}
231		if echo2.Status != StatusWaiting || echo2.Attempts != 1 || echo2.NextRetry != 1_700_000_001_000 {
232			t.Fatalf("waiting record must be unchanged after early advance: %+v", echo2)
233		}
234	
235		// Coverage arrives, delivery happens only at the scheduled retry.
236		q.UpsertHeader(Header{Chain: "chain-a", Height: 110, Root: "0x110", Trusted: true})
237		rep, err = q.Advance(1_700_000_001_000)
238		if err != nil {
239			t.Fatal(err)
240		}
241		if len(rep.Results) != 1 || rep.Results[0].Status != StatusSuccess {
242			t.Fatalf("want delivery at scheduled retry, got %+v", rep.Results)
243		}
244	}
245	
246	// A conflicting submit against a waiting record leaves its content, status,
247	// reason, attempt count and retry schedule exactly as they were, including
248	// when only the proof height or the expiry changes.
249	func TestSubmitConflictWhileWaitingKeepsRecordAndSchedule(t *testing.T) {
250		q, _ := openTempQueue(t)
251		defer q.Close()
252		q.RegisterSource("chain-a")
253		q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "0x100", Trusted: true})
254	
255		env := Envelope{
256			Message:   Message{ID: "w", From: "chain-a", To: "chain-b", Nonce: 8, Payload: "world", ProofAt: 110},
257			ExpiresAt: 9_000_000_000_000,
258		}
259		q.Submit(env)
260		q.Advance(1_700_000_000_000)
261		before := statusOf(t, q, "w")
262		beforeQ, _ := q.Query("w")
263	
264		for _, mutate := range []func(Envelope) Envelope{
265			func(e Envelope) Envelope { e.Message.ProofAt = 111; return e },
266			func(e Envelope) Envelope { e.ExpiresAt = 9_000_000_000_001; return e },
267			func(e Envelope) Envelope { e.Message.Payload = "WORLD"; return e },
268			func(e Envelope) Envelope { e.Message.Nonce = 9; return e },
269			func(e Envelope) Envelope { e.Message.From = "chain-a2"; return e },
270			func(e Envelope) Envelope { e.Message.To = "chain-c"; return e },
271		} {
272			if _, err := q.Submit(mutate(env)); !errors.Is(err, ErrConflict) {
273				t.Fatalf("waiting content change must be ErrConflict: %v", err)
274			}
275			got := statusOf(t, q, "w")
276			if got.Status != before.Status || got.Reason != before.Reason ||
277				got.Attempts != before.Attempts || got.NextRetry != before.NextRetry ||
278				got.Msg != before.Msg {
279				t.Fatalf("waiting record changed on rejected submit:\nbefore=%+v\nafter =%+v", before, got)
280			}
281		}
282		if got, _ := q.Query("w"); got != beforeQ {
283			t.Fatalf("query view changed: %+v", got)
284		}
285		if len(q.order) != 1 {
286			t.Fatalf("conflict added a queue entry: %v", q.order)
287		}
288	}
289	
290	// A rejected submit against one message changes neither sibling content nor
291	// the first-submission order of the live records.
292	func TestSubmitConflictLeavesSiblingsAndOrderUntouched(t *testing.T) {
293		q, _ := openTempQueue(t)
294		defer q.Close()
295	
296		a := env("a", "a", "b", 1, 10, 0)
297		m := Envelope{Message: Message{ID: "m", From: "a", To: "b", Nonce: 5, Payload: "orig", ProofAt: 20}, ExpiresAt: 0}
298		b := env("b", "a", "b", 9, 30, 0)
299		for _, e := range []Envelope{a, m, b} {
300			if _, err := q.Submit(e); err != nil {
301				t.Fatal(err)
302			}
303		}
304	
305		bad := m
306		bad.Message.ProofAt = 21
307		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
308			t.Fatalf("want ErrConflict, got %v", err)
309		}
310	
311		all := q.Queries()
312		if len(all) != 3 || all[0].ID != "a" || all[1].ID != "m" || all[2].ID != "b" {
313			t.Fatalf("order changed by rejected submit: %+v", all)
314		}
315		if all[1].Payload != "orig" || all[1].ProofAt != 20 {
316			t.Fatalf("target content overwritten: %+v", all[1])
317		}
318		if all[0].ProofAt != 10 || all[2].ProofAt != 30 {
319			t.Fatalf("sibling content changed: %+v %+v", all[0], all[2])
320		}
321	}
322	
323	// A rejected conflict must survive a process restart with nothing added: only
324	// the original record exists, with the original content, pending state and
325	// seq.
326	func TestSubmitConflictPersistsNothingAcrossReopen(t *testing.T) {
327		dir := t.TempDir()
328		q, err := Open(dir)
329		if err != nil {
330			t.Fatal(err)
331		}
332		base := fullEnvelope("m")
333		if _, err := q.Submit(base); err != nil {
334			t.Fatal(err)
335		}
336		bad := base
337		bad.Message.ProofAt = 1000
338		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
339			t.Fatalf("want ErrConflict, got %v", err)
340		}
341		if err := q.Close(); err != nil {
342			t.Fatal(err)
343		}
344	
345		q2, err := Open(dir)
346		if err != nil {
347			t.Fatal(err)
348		}
349		defer q2.Close()
350		if len(q2.records) != 1 || q2.nextSeq != 1 {
351			t.Fatalf("rejected submit leaked into the log: records=%d nextSeq=%d", len(q2.records), q2.nextSeq)
352		}
353		got := statusOf(t, q2, "m")
354		if got.Msg != base || got.Status != StatusPending {
355			t.Fatalf("record after reopen wrong: %+v", got)
356		}
357		// Original content still resubmits idempotently after reopen.
358		if _, err := q2.Submit(base); err != nil {
359			t.Fatalf("identical resubmit after reopen: %v", err)
360		}
361		if len(q2.records) != 1 {
362			t.Fatal("identical resubmit after reopen added a record")
363		}
364	}
365	
366	// Once a message is terminal, identical and differing content alike return
367	// ErrTerminal (never ErrConflict), for success as well as the other terminal
368	// statuses; the stored record stays queryable with its status and reason.
369	func TestSubmitTerminalIDAlwaysErrTerminal(t *testing.T) {
370		t.Run("success", func(t *testing.T) {
371			q, _ := openTempQueue(t)
372			defer q.Close()
373			q.RegisterSource("a")
374			q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
375			e := env("m", "a", "b", 1, 10, 0)
376			q.Submit(e)
377			q.Advance(1000)
378	
379			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
380				t.Fatalf("identical resubmit of a success: want ErrTerminal, got %v", err)
381			}
382			bad := e
383			bad.Message.ProofAt = 11
384			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
385				t.Fatalf("different content on a success: want ErrTerminal, got %v", err)
386			}
387			got := statusOf(t, q, "m")
388			if got.Status != StatusSuccess || got.NextRetry != 0 {
389				t.Fatalf("success record changed: %+v", got)
390			}
391			// Advancing time again must not redeliver.
392			rep, err := q.Advance(2000)
393			if err != nil {
394				t.Fatal(err)
395			}
396			if len(rep.Results) != 0 {
397				t.Fatalf("terminal message reappeared on advance: %+v", rep.Results)
398			}
399		})
400	
401		t.Run("expired", func(t *testing.T) {
402			q, _ := openTempQueue(t)
403			defer q.Close()
404			q.RegisterSource("a")
405			e := env("m", "a", "b", 1, 1000, 2000)
406			q.Submit(e)
407			q.Advance(1000) // waiting
408			q.Advance(2000) // expired
409			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
410				t.Fatalf("identical resubmit of expired: %v", err)
411			}
412			bad := e
413			bad.Message.Payload = "x"
414			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
415				t.Fatalf("different content on expired: want ErrTerminal, got %v", err)
416			}
417			if got := statusOf(t, q, "m"); got.Status != StatusExpired {
418				t.Fatalf("expired record changed: %+v", got)
419			}
420		})
421	
422		t.Run("unknown-source", func(t *testing.T) {
423			q, _ := openTempQueue(t)
424			defer q.Close()
425			e := env("m", "ghost", "b", 1, 10, 0)
426			q.Submit(e)
427			q.Advance(1000)
428			if _, err := q.Submit(e); !errors.Is(err, ErrTerminal) {
429				t.Fatalf("identical resubmit of unknown-source: %v", err)
430			}
431			bad := e
432			bad.Message.ProofAt = 11
433			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
434				t.Fatalf("different content on unknown-source: want ErrTerminal, got %v", err)
435			}
436			if got := statusOf(t, q, "m"); got.Status != StatusUnknownSrc {
437				t.Fatalf("unknown-source record changed: %+v", got)
438			}
439		})
440	
441		t.Run("replay", func(t *testing.T) {
442			q, _ := openTempQueue(t)
443			defer q.Close()
444			q.RegisterSource("a")
445			q.UpsertHeader(Header{Chain: "a", Height: 100, Trusted: true})
446			winner := env("win", "a", "b", 3, 10, 0)
447			loser := env("lose", "a", "b", 3, 10, 0)
448			q.Submit(winner)
449			q.Submit(loser)
450			q.Advance(1000)
451			if _, err := q.Submit(loser); !errors.Is(err, ErrTerminal) {
452				t.Fatalf("identical resubmit of replay record: %v", err)
453			}
454			bad := loser
455			bad.Message.Payload = "p-changed"
456			if _, err := q.Submit(bad); !errors.Is(err, ErrTerminal) {
457				t.Fatalf("different content on replay record: want ErrTerminal, got %v", err)
458			}
459			if got := statusOf(t, q, "lose"); got.Status != StatusReplay {
460				t.Fatalf("replay record changed: %+v", got)
461			}
462		})
463	}
