			T: kindState, Now: 1000, ID: "m", Status: StatusSuccess, Attempts: 1,
			ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
		}))...)
		writeRawLog(t, dir, raw)
		assertCorruptAndUntouched(t, dir, raw)
	})
